WHEN MATCHED THEN UPDATE SET
  t.LABEL = s.LABEL, t.PARENT_KEY = s.PARENT_KEY,
  t.IS_ACTIVE = TRUE, t.TAXONOMY_VERSION = 'v3'
WHEN NOT MATCHED THEN INSERT
  (CATEGORY_KEY, LABEL, PARENT_KEY, IS_ACTIVE, TAXONOMY_VERSION)
  VALUES (s.CATEGORY_KEY, s.LABEL, s.PARENT_KEY, TRUE, 'v3');

UPDATE PAPERSONAR.PROJECT_REF.REF_CATEGORY
SET IS_ACTIVE = FALSE
WHERE TAXONOMY_VERSION IS DISTINCT FROM 'v3';

