) s
ON t.SOURCE_NAME = s.SOURCE_NAME AND t.SOURCE_VALUE = s.SOURCE_VALUE
WHEN MATCHED THEN UPDATE SET
  t.CATEGORY_KEY = s.CATEGORY_KEY, t.MAPPING_VERSION = 'v3',
  t.IS_ACTIVE = TRUE
WHEN NOT MATCHED THEN INSERT
  (SOURCE_NAME, SOURCE_VALUE, CATEGORY_KEY, MAPPING_VERSION, IS_ACTIVE)
  VALUES (s.SOURCE_NAME, s.SOURCE_VALUE, s.CATEGORY_KEY, 'v3', TRUE);

UPDATE PAPERSONAR.PROJECT_REF.REF_TAXONOMY_MAP
SET IS_ACTIVE = FALSE
WHERE MAPPING_VERSION IS DISTINCT FROM 'v3';
